     9→import Combine
    10→import Foundation
    11→import MatrixRustSDK
    12→
    13→class AuthenticationService: AuthenticationServiceProtocol {
    14→    private var client: ClientProtocol?
    15→    private var sessionDirectories: SessionDirectories
    16→    private let passphrase: String
    17→    
    18→    private let clientFactory: AuthenticationClientFactoryProtocol
    19→    private let userSessionStore: UserSessionStoreProtocol
    20→    private let appSettings: AppSettings
    21→    private let appHooks: AppHooks
    22→    
    23→    private let homeserverSubject: CurrentValueSubject<LoginHomeserver, Never>
    24→    var homeserver: CurrentValuePublisher<LoginHomeserver, Never> { homeserverSubject.asCurrentValuePublisher() }
    25→    private(set) var flow: AuthenticationFlow
    26→    
    27→    init(userSessionStore: UserSessionStoreProtocol,
    28→         encryptionKeyProvider: EncryptionKeyProviderProtocol,
    29→         clientFactory: AuthenticationClientFactoryProtocol = AuthenticationClientFactory(),
    30→         appSettings: AppSettings,
    31→         appHooks: AppHooks) {
    32→        sessionDirectories = .init()
    33→        passphrase = encryptionKeyProvider.generateKey().base64EncodedString()
    34→        self.clientFactory = clientFactory
    35→        self.userSessionStore = userSessionStore
    36→        self.appSettings = appSettings
    37→        self.appHooks = appHooks
    38→        
    39→        // When updating these, don't forget to update the reset method too.
    40→        homeserverSubject = .init(LoginHomeserver(address: appSettings.accountProviders[0], loginMode: .unknown))
    41→        flow = .login
    42→    }
    43→    
    44→    // MARK: - Public
    45→    
    46→    func configure(for homeserverAddress: String, flow: AuthenticationFlow) async -> Result<Void, AuthenticationServiceError> {
    47→        do {
    48→            var homeserver = LoginHomeserver(address: homeserverAddress, loginMode: .unknown)
    49→            
    50→            let client = try await makeClient(homeserverAddress: homeserverAddress)
    51→            let loginDetails = await client.homeserverLoginDetails()
    52→            
    53→            homeserver.loginMode = if loginDetails.supportsOidcLogin() {
    54→                .oidc(supportsCreatePrompt: loginDetails.supportedOidcPrompts().contains(.create))
    55→            } else if loginDetails.supportsPasswordLogin() {
    56→                .password
    57→            } else {
    58→                .unsupported
    59→            }
    60→            
    61→            if flow == .login, homeserver.loginMode == .unsupported {
    62→                return .failure(.loginNotSupported)
    63→            }
    64→            if flow == .register, !homeserver.loginMode.supportsOIDCFlow {
    65→                return .failure(.registrationNotSupported)
    66→            }
    67→            
    68→            self.client = client
    69→            self.flow = flow
    70→            homeserverSubject.send(homeserver)
    71→            return .success(())
    72→        } catch ClientBuildError.WellKnownDeserializationError(let error) {
    73→            MXLog.error("The user entered a server with an invalid well-known file: \(error)")
    74→            return .failure(.invalidWellKnown(error))
    75→        } catch ClientBuildError.SlidingSyncVersion(let error) {
    76→            MXLog.info("User entered a homeserver that isn't configured for sliding sync: \(error)")
    77→            return .failure(.slidingSyncNotAvailable)
    78→        } catch RemoteSettingsError.elementProRequired(let serverName) {
    79→            return .failure(.elementProRequired(serverName: serverName))
    80→        } catch {
    81→            MXLog.error("Failed configuring a server: \(error)")
    82→            return .failure(.invalidHomeserverAddress)
    83→        }
    84→    }
    85→    
    86→    func urlForOIDCLogin(loginHint: String?) async -> Result<OIDCAuthorizationDataProxy, AuthenticationServiceError> {
    87→        guard let client else { return .failure(.oidcError(.urlFailure)) }
    88→        do {
    89→            // The create prompt is broken: https://github.com/element-hq/matrix-authentication-service/issues/3429
    90→            // let prompt: OidcPrompt = flow == .register ? .create : .consent
    91→            let oidcData = try await client.urlForOidc(oidcConfiguration: appSettings.oidcConfiguration.rustValue,
    92→                                                       prompt: .consent,
    93→                                                       loginHint: loginHint,
    94→                                                       deviceId: nil,
    95→                                                       additionalScopes: nil)
    96→            return .success(OIDCAuthorizationDataProxy(underlyingData: oidcData))
    97→        } catch {
    98→            MXLog.error("Failed to get URL for OIDC login: \(error)")
    99→            return .failure(.oidcError(.urlFailure))
   100→        }
   101→    }
   102→    
   103→    func abortOIDCLogin(data: OIDCAuthorizationDataProxy) async {
   104→        guard let client else { return }
   105→        MXLog.info("Aborting OIDC login.")
   106→        await client.abortOidcAuth(authorizationData: data.underlyingData)
   107→    }
   108→    
   109→    func loginWithOIDCCallback(_ callbackURL: URL) async -> Result<UserSessionProtocol, AuthenticationServiceError> {
   110→        guard let client else { return .failure(.failedLoggingIn) }
   111→        do {
   112→            try await client.loginWithOidcCallback(callbackUrl: callbackURL.absoluteString)
   113→            return await userSession(for: client)
   114→        } catch OidcError.Cancelled {
   115→            return .failure(.oidcError(.userCancellation))
   116→        } catch {
   117→            MXLog.error("Login with OIDC failed: \(error)")
   118→            return .failure(.failedLoggingIn)
   119→        }
   120→    }
   121→    
   122→    func login(username: String, password: String, initialDeviceName: String?, deviceID: String?) async -> Result<UserSessionProtocol, AuthenticationServiceError> {
   123→        guard let client else { return .failure(.failedLoggingIn) }
   124→        do {
   125→            try await client.login(username: username, password: password, initialDeviceName: initialDeviceName, deviceId: deviceID)
   126→            
   127→            let refreshToken = try? client.session().refreshToken
   128→            if refreshToken != nil {
   129→                MXLog.warning("Refresh token found for a non oidc session, can't restore session, logging out")
   130→                _ = try? await client.logout()
   131→                return .failure(.sessionTokenRefreshNotSupported)
   132→            }
   133→            
   134→            return await userSession(for: client)
   135→        } catch let ClientError.MatrixApi(errorKind, _, _, _) {
   136→            MXLog.error("Failed logging in with error kind: \(errorKind)")
   137→            switch errorKind {
   138→            case .forbidden:
   139→                return .failure(.invalidCredentials)
   140→            case .userDeactivated:
   141→                return .failure(.accountDeactivated)
   142→            default:
   143→                return .failure(.failedLoggingIn)
   144→            }
   145→        } catch {
   146→            MXLog.error("Failed logging in with error: \(error)")
   147→            return .failure(.failedLoggingIn)
   148→        }
   149→    }
   150→    
   151→    func loginWithQRCode(data: Data) -> QRLoginProgressPublisher {
   152→        let progressSubject = CurrentValueSubject<QRLoginProgress, AuthenticationServiceError>(.starting)
   153→        
   154→        let qrData: QrCodeData
   155→        do {
   156→            qrData = try QrCodeData.fromBytes(bytes: data)
   157→        } catch {
   158→            MXLog.error("QRCode decode error: \(error)")
   159→            progressSubject.send(completion: .failure(.qrCodeError(.invalidQRCode)))
   160→            return progressSubject.asCurrentValuePublisher()
   161→        }
   162→        
   163→        guard let scannedServerName = qrData.serverName() else {
   164→            MXLog.error("The QR code is from a device that is not yet signed in.")
   165→            progressSubject.send(completion: .failure(.qrCodeError(.deviceNotSignedIn)))
   166→            return progressSubject.asCurrentValuePublisher()
   167→        }
   168→        
   169→        if !appSettings.allowOtherAccountProviders, !appSettings.accountProviders.contains(scannedServerName) {
   170→            MXLog.error("The scanned device's server is not allowed: \(scannedServerName)")
   171→            progressSubject.send(completion: .failure(.qrCodeError(.providerNotAllowed(scannedProvider: scannedServerName, allowedProviders: appSettings.accountProviders))))
   172→            return progressSubject.asCurrentValuePublisher()
   173→        }
   174→        
   175→        let listener = SDKListener { progress in
   176→            guard let progress = QRLoginProgress(rustProgress: progress) else { return }
   177→            progressSubject.send(progress)
   178→        }
   179→        
   180→        Task {
   181→            do {
   182→                let client = try await makeClient(homeserverAddress: scannedServerName)
   183→                let qrCodeHandler = client.newLoginWithQrCodeHandler(oidcConfiguration: appSettings.oidcConfiguration.rustValue)
   184→                try await qrCodeHandler.scan(qrCodeData: qrData, progressListener: listener)
   185→                
   186→                switch await userSession(for: client) {
   187→                case .success(let userSession):
   188→                    progressSubject.send(.signedIn(userSession))
   189→                case .failure(let error):
   190→                    progressSubject.send(completion: .failure(error))
   191→                }
   192→            } catch let error as HumanQrLoginError {
   193→                MXLog.error("QRCode login error: \(error)")
   194→                progressSubject.send(completion: .failure(error.serviceError))
   195→            } catch RemoteSettingsError.elementProRequired(let serverName) {
   196→                progressSubject.send(completion: .failure(.elementProRequired(serverName: serverName)))
   197→            } catch {
   198→                MXLog.error("QRCode login unknown error: \(error)")
   199→                progressSubject.send(completion: .failure(.qrCodeError(.unknown)))
   200→            }

